insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('22e6ee9b-e252-4796-b851-27e1fe3c86d6', '0f05899c-9d3e-434e-9a44-cdb360720482', $$inleiding: herintroductie van przewalskipaarden sinds 1992$$,
   $$biologie-vwo-2024-ii-de-herintroductie-van-het-przewalskipaard-context1.png$$,
   $$In 1969 stierven przewalskipaarden uit in het wild. Vanaf 1992 worden przewalskipaarden uit dierentuinen geherintroduceerd in hun natuurlijke habitat. In 2020 maakte San Diego Zoo Global bekend dat het eerste gekloonde przewalskipaard was geboren in hun dierentuin.$$, 'inline'),
  ('5fc3e17d-1474-48bd-97e5-1ecd7014766f', '0f05899c-9d3e-434e-9a44-cdb360720482', $$taxonomie van het przewalskipaard: Equus-namen en chromosomenaantal (afbeelding 1)$$,
   $$biologie-vwo-2024-ii-de-herintroductie-van-het-przewalskipaard-context2.png$$,
   $$Het przewalskipaard behoort tot de familie van de paardachtigen. Over de wetenschappelijke naam zijn taxonomen het nog steeds niet eens. Het przewalskipaard (afbeelding 1) wordt aangeduid als Equus przewalskii of als Equus ferus przewalskii. Het ‘gewone’ paard, dat door de mens tam is gemaakt (gedomesticeerd), heeft de naam Equus ferus caballus. Het genoom van deze dieren is verschillend: het przewalskipaard heeft 66 chromosomen; het gewone paard heeft 64 chromosomen. Een kruising van een gewoon paard met een przewalskipaard levert vruchtbare nakomelingen (F1) op met 65 chromosomen.
afbeelding 1$$, 'inline'),
  ('a7394afb-59a4-4f48-8a6a-a693f208d49e', '0f05899c-9d3e-434e-9a44-cdb360720482', $$keuzevraag: welke wetenschappelijke naam krijgt het przewalskipaard?$$,
   $$biologie-vwo-2024-ii-de-herintroductie-van-het-przewalskipaard-context3.png$$,
   $$Stel dat jij mag bepalen welke van de twee wetenschappelijke namen het przewalskipaard krijgt.$$, 'inline'),
  ('7591d4b0-4898-4794-b48e-995f3c06642c', '0f05899c-9d3e-434e-9a44-cdb360720482', $$onderzoek naar verwantschap met eerste gedomesticeerde paarden; cladogram (afbeelding 2)$$,
   $$biologie-vwo-2024-ii-de-herintroductie-van-het-przewalskipaard-context4.png$$,
   $$Lange tijd werd aangenomen dat przewalskipaarden wilde paarden zijn: de voorouders van przewalskipaarden zouden nooit gedomesticeerd zijn geweest. Daarmee zouden przewalskipaarden de enige nog levende wilde paarden zijn. Wetenschappers uit verschillende landen hebben onderzocht of dat inderdaad zo is. Het genoom van de eerste gedomesticeerde paarden uit Kazachstan (botaj-paarden en borly- paarden, die circa 5000 jaar geleden leefden) werd vergeleken met dat van andere groepen paarden. Op grond van de resultaten is een cladogram opgesteld (afbeelding 2).
afbeelding 2$$, 'inline'),
  ('6c397c7f-4254-4713-8dc7-a5466d9a61d8', '0f05899c-9d3e-434e-9a44-cdb360720482', $$drie uitspraken over het cladogram$$,
   $$biologie-vwo-2024-ii-de-herintroductie-van-het-przewalskipaard-context5.png$$,
   $$Over het cladogram worden de volgende uitspraken gedaan:
1 De huidige przewalskipaarden zijn wilde paarden.
2 De ezels zijn voorouders van de huidige przewalskipaarden.
3 De huidige przewalskipaarden zijn meer verwant aan huidige gedomesticeerde paarden dan aan prehistorische wilde paarden.$$, 'inline'),
  ('fb26f2c7-e644-4525-b3cd-a38f179d3c5a', '0f05899c-9d3e-434e-9a44-cdb360720482', $$in de vorige eeuw gevangen przewalskipaarden, twaalf succesvolle fokdieren$$,
   $$biologie-vwo-2024-ii-de-herintroductie-van-het-przewalskipaard-context6.png$$,
   $$In de eerste helft van de vorige eeuw werden tientallen przewalskipaarden gevangen om in dierentuinen te houden. Uiteindelijk hebben slechts twaalf dieren zich daar succesvol voortgeplant. Alle nu levende przewalskipaarden stammen af van deze dieren.$$, 'inline'),
  ('70ff39e7-7faf-416a-8e00-725173529db3', '0f05899c-9d3e-434e-9a44-cdb360720482', $$de enorme afname van het aantal przewalskipaarden verkleinde de genenpool$$,
   $$biologie-vwo-2024-ii-de-herintroductie-van-het-przewalskipaard-context7.png$$,
   $$Door de enorme afname van het aantal przewalskipaarden is de genenpool afgenomen.$$, 'inline'),
  ('2ad97269-cc70-488a-86e3-9047238eb1a3', '0f05899c-9d3e-434e-9a44-cdb360720482', $$kleine populatie leidde tot inteelt; drie uitspraken over inteelt$$,
   $$biologie-vwo-2024-ii-de-herintroductie-van-het-przewalskipaard-context8.png$$,
   $$De kleine populatie przewalskipaarden heeft geleid tot inteelt bij de nakomelingen. Over inteelt worden de volgende uitspraken gedaan:
1 Door inteelt neemt de kans op het ontstaan van mutaties toe.
2 Inteelt vergroot de kans op een lagere fitness van de nakomelingen.
3 Door inteelt neemt het aandeel heterozygoten in de populatie toe.$$, 'inline'),
  ('a10386fb-6251-4fb7-8cea-0660edb21312', '0f05899c-9d3e-434e-9a44-cdb360720482', $$herintroductieplan van Groeneveld en Bouman; voorbereiding in Flevoland$$,
   $$biologie-vwo-2024-ii-de-herintroductie-van-het-przewalskipaard-context9.png$$,
   $$De Nederlandse biologen Annette Groeneveld en Inge en Jan Bouman maakten in 1977 een plan voor de herintroductie van przewalskipaarden in Mongolië. Zij haalden przewalskipaarden uit dierentuinen en bereidden de dieren in een natuurgebied in Flevoland voor op herintroductie. Tussen 1992 en 2000 zijn 82 ‘Flevolandse’ przewalskipaarden uitgezet in de Gobi-woestijn in Mongolië.$$, 'inline'),
  ('b0de13ac-35a5-42d5-b4d6-2c30271e8a73', '0f05899c-9d3e-434e-9a44-cdb360720482', $$invuloefening over niche/habitat en successiesnelheid in het Flevolandse gebied$$,
   $$biologie-vwo-2024-ii-de-herintroductie-van-het-przewalskipaard-context10.png$$,
   $$De tekst hieronder beschrijft het verblijf van de przewalskipaarden in het natuurgebied in Flevoland. Op de plaatsen 1 en 2 ontbreekt een woord.
Door de przewalskipaarden te plaatsen in het natuurgebied in Flevoland, konden de dieren wennen aan de omstandigheden in het wild. Omdat er geen andere paarden voorkwamen in het gebied, was ...(1)... van de prezwalskipaarden nog niet bezet. Door de przewalskipaarden werd de successie in het gebied ...(2)... .$$, 'inline'),
  ('1d8a4a8c-d659-4bf4-b28e-2494ed3e630f', '0f05899c-9d3e-434e-9a44-cdb360720482', $$fokprogramma''s met frozen zoo-materiaal; kloonprocedure in San Diego Zoo Global (afbeelding 3)$$,
   $$biologie-vwo-2024-ii-de-herintroductie-van-het-przewalskipaard-context11.png$$,
   $$Wetenschappers proberen met fokprogramma’s de genetische diversiteit van de populatie przewalskipaarden te vergroten. Hierbij maken ze onder andere gebruik van genetisch materiaal dat is ingevroren en opgeslagen in een ‘frozen zoo’. Het gekloonde przewalskipaard in San Diego Zoo Global is hier een voorbeeld van. De wetenschappers gebruikten hierbij een eicel van een gedomesticeerd paard en de celkern van een ingevroren huidcel van een przewalski-hengst. Afbeelding 3 toont de werkwijze van de wetenschappers.
afbeelding 3$$, 'inline'),
  ('3c12600a-08ce-482e-8f59-3d3d71500708', '0f05899c-9d3e-434e-9a44-cdb360720482', $$opgeslagen hengstcellen in de frozen zoo; sequencing om geschikte hengst te kiezen$$,
   $$biologie-vwo-2024-ii-de-herintroductie-van-het-przewalskipaard-context12.png$$,
   $$In de frozen zoo waren cellen van verschillende hengsten opgeslagen. Om een geschikte hengst te kiezen voor het fokprogramma, werd sequencing toegepast.$$, 'inline'),
  ('9f4e35ed-4673-40d3-874a-df2e2b18dc16', '0f05899c-9d3e-434e-9a44-cdb360720482', $$cellen P, Q en R aangegeven in afbeelding 3$$,
   $$biologie-vwo-2024-ii-de-herintroductie-van-het-przewalskipaard-context13.png$$,
   $$In afbeelding 3 zijn cellen aangegeven met P, Q en R.$$, 'inline'),
  ('6172354e-7e11-4af4-afaf-a1af2bfc479c', '0f05899c-9d3e-434e-9a44-cdb360720482', $$het genoom van het kloonveulen is niet volledig identiek aan dat van de hengst$$,
   $$biologie-vwo-2024-ii-de-herintroductie-van-het-przewalskipaard-context14.png$$,
   $$De procedure die gebruikt is in San Diego Zoo Global levert een veulen op waarvan het genoom niet volledig identiek is aan dat van de gebruikte hengst.$$, 'inline'),
  ('9af2da01-0f54-45be-ad87-df01e9ee6b97', '9c6eb2dd-806d-4cf0-acc6-707cffe374f7', $$inleiding: Nick is allergisch voor ambrosiapollen; kenmerken van ambrosia (afbeelding 1)$$,
   $$biologie-vwo-2024-ii-bestrijding-van-ambrosia-context1.png$$,
   $$Ambrosia is een plant uit Noord-Amerika die eind negentiende eeuw voor het eerst in Nederland werd waargenomen. Nick is allergisch voor de pollen van ambrosia, waardoor hij vaak last heeft van hooikoorts.
Ambrosia of alsemambrosia (Ambrosia afbeelding 1 artemisiifolia, afbeelding 1) is een eenjarige plant. De plant komt voor op verstoorde gronden, zoals omgewerkte bermen, akkers, fabrieks- en bouwterreinen. De onopvallende bloemen produceren een grote hoeveelheid stuifmeel (pollen), waar veel mensen een allergie voor ontwikkelen. Ook het aantal geproduceerde zaden is enorm groot. Het zaad kan meer dan 40 jaar kiemkrachtig blijven. De zaden van ambrosia zijn via hooi en vogelvoer in Nederland terechtgekomen. In Nederland kan de plant alleen in warme zomers kiemkrachtige zaden produceren.$$, 'inline'),
  ('84d183f6-29b6-4c33-87f2-28d3b4223850', '9c6eb2dd-806d-4cf0-acc6-707cffe374f7', $$ambrosia lijkt zich pas de laatste jaren in Nederland te hebben gevestigd$$,
   $$biologie-vwo-2024-ii-bestrijding-van-ambrosia-context2.png$$,
   $$Ambrosia wordt al meer dan een eeuw regelmatig in Nederland waargenomen. Toch lijkt de plant zich pas de laatste jaren in Nederland te hebben gevestigd: de plant kan er nu zijn hele levenscyclus voltooien.$$, 'inline'),
  ('d995ecdf-479c-4364-99c8-341801162266', '9c6eb2dd-806d-4cf0-acc6-707cffe374f7', $$krastest met positieve en negatieve controle (afbeelding 2)$$,
   $$biologie-vwo-2024-ii-bestrijding-van-ambrosia-context3.png$$,
   $$Nicks allergie werd vastgesteld met behulp van een krastest. Bij een krastest worden verschillende soorten pollen – in een oplosmiddel – aangebracht in een krasje in de huid. Daarnaast worden een positieve en een negatieve controle aangebracht. Voor de positieve controle wordt de lichaamseigen stof (mediator) gebruikt die verantwoordelijk is voor het ontstaan van allergische reacties. Voor de negatieve controle wordt het oplosmiddel zonder pollen gebruikt. Na korte tijd kan de reactie beoordeeld worden aan de hand van   afbeelding 2 de mate van zwelling en roodheid (afbeelding 2).$$, 'inline'),
  ('7faf24f4-5ce3-4979-be8d-ec239ae847ee', '9c6eb2dd-806d-4cf0-acc6-707cffe374f7', $$mechanisme van de allergische astma-aanval: histamine, bronchoconstrictie en slijm$$,
   $$biologie-vwo-2024-ii-bestrijding-van-ambrosia-context4.png$$,
   $$Blootstelling aan ambrosiapollen leidt bij Nick tot een allergische astma- aanval. Na blootstelling trekken – onder invloed van de mediator histamine – de spieren in de wand van zijn bronchiolen zich samen en zwelt het slijmvlies op. Ook wordt er meer en dikker slijm geproduceerd dan normaal. Deze reacties leiden ertoe dat sommige bronchiolen geen lucht doorlaten. Het gevormde slijm komt niet in de longblaasjes terecht.$$, 'inline'),
  ('01b1e206-ffda-453a-96eb-efe5ed43813b', '9c6eb2dd-806d-4cf0-acc6-707cffe374f7', $$drie uitspraken over de allergische reactie$$,
   $$biologie-vwo-2024-ii-bestrijding-van-ambrosia-context5.png$$,
   $$Over deze allergische reactie worden de volgende uitspraken gedaan:
1 De slijmproductie is onderdeel van het verworven afweersysteem.
2 Er treedt bloedvatvernauwing op in de slijmvliezen.
3 Bij een allergische reactie produceert het lichaam overdreven veel antigenen tegen pollen.$$, 'inline'),
  ('f0048212-6189-47a4-b3f2-35ba217af1c0', '9c6eb2dd-806d-4cf0-acc6-707cffe374f7', $$factoren van de gaswisseling (D, A, ∆c, ∆x); veranderingen tijdens een astma-aanval$$,
   $$biologie-vwo-2024-ii-bestrijding-van-ambrosia-context6.png$$,
   $$Door de reacties in de luchtwegen bij een allergische astma-aanval wordt de gaswisseling in de longen beïnvloed. Factoren die van invloed zijn op de snelheid van de gaswisseling zijn de diffusiecoëfficiënt (D), het diffusie-oppervlak (A), het verschil in partiële druk (∆c) en de diffusieafstand (∆x). Bij een allergische astma-aanval veranderen A en ∆c.$$, 'inline'),
  ('9264d731-03a5-44cc-8310-8bb1dbe5e8ba', '9c6eb2dd-806d-4cf0-acc6-707cffe374f7', $$het samentrekken van de bronchiolen door een deel van het zenuwstelsel$$,
   $$biologie-vwo-2024-ii-bestrijding-van-ambrosia-context7.png$$,
   $$Het samentrekken van spieren in de wand van de bronchiolen wordt veroorzaakt door activiteit in een deel van het zenuwstelsel.$$, 'inline'),
  ('3cfae324-d090-4bcc-ac18-0f6ea27df042', '9c6eb2dd-806d-4cf0-acc6-707cffe374f7', $$spirometertest en spirogram van Nick en een persoon zonder astma (afbeelding 3)$$,
   $$biologie-vwo-2024-ii-bestrijding-van-ambrosia-context8.png$$,
   $$Met een spirometertest wordt Nicks longfunctie bepaald. Tijdens de test wordt een spirogram gemaakt (afbeelding 3). Voor de test moet Nick eerst zo diep mogelijk inademen. Dan begint de test. Nick moet daarbij:
− zo hard en lang mogelijk uitademen (afbeelding 3, bovenkant diagram),
− vervolgens weer volledig inademen (afbeelding 3, onderkant diagram). Tijdens de test worden de volgende grootheden gemeten:
− het volume van de uitgeademde lucht en van de ingeademde lucht
− de snelheid van de luchtstroom tijdens uitademing en tijdens inademing Afbeelding 3 toont het verband tussen deze grootheden bij Nick en bij een persoon zonder astma.
afbeelding 3$$, 'inline'),
  ('18363844-5031-4a77-b711-8eb57ae683e2', '9c6eb2dd-806d-4cf0-acc6-707cffe374f7', $$drie uitspraken over afbeelding 3$$,
   $$biologie-vwo-2024-ii-bestrijding-van-ambrosia-context9.png$$,
   $$Over afbeelding 3 worden de volgende uitspraken gedaan:
1 De hoogste snelheid wordt bereikt aan het einde van de uitademing.
2 De maximale waarde van de grafiek op de x-as is gelijk aan de totale longcapaciteit (VTC of TLC).
3 De vitale capaciteit (VC) van Nick is gelijk aan die van de persoon zonder astma.$$, 'inline'),
  ('9affb7a9-7efa-4c32-918b-7fa07dba4774', '9c6eb2dd-806d-4cf0-acc6-707cffe374f7', $$het bladhaantje Ophraella communa als bestrijder van ambrosia; introductie in Italië$$,
   $$biologie-vwo-2024-ii-bestrijding-van-ambrosia-context10.png$$,
   $$Nick leest dat ambrosia in Europa kan worden bestreden met het bladhaantje Ophraella communa. Deze blad-etende kever is afkomstig uit Noord-Amerika en heeft een voorkeur voor ambrosia. Bij gebrek aan ambrosia eet de soort daar ook van andere planten, zoals zonnebloemen. O. communa werd in 2013 per ongeluk in Italië geïntroduceerd. Uit onderzoek blijkt dat de hoeveelheid ambrosiapollen in het gebied met 82% afnam en dat de kever er nauwelijks van andere planten at.$$, 'inline'),
  ('9dc21541-57f3-425d-b5cc-6a266176a2de', '9c6eb2dd-806d-4cf0-acc6-707cffe374f7', $$de natuurlijke aanwezigheid van O. communa bestrijdt ambrosia in Noord-Amerika niet effectief$$,
   $$biologie-vwo-2024-ii-bestrijding-van-ambrosia-context11.png$$,
   $$In Noord-Amerika is de natuurlijke aanwezigheid van O. communa niet effectief om overlast door ambrosia tegen te gaan.$$, 'inline'),
  ('daa984d4-8e14-4155-af9f-63d24bc14fac', '9c6eb2dd-806d-4cf0-acc6-707cffe374f7', $$ecologisch model met tolerantiecurven van ambrosia en O. communa (afbeelding 4)$$,
   $$biologie-vwo-2024-ii-bestrijding-van-ambrosia-context12.png$$,
   $$Wetenschappers onderzochten met behulp van een ecologisch model of O. communa ook in andere delen van Europa ingezet kan worden. Met het model zijn de tolerantiecurven van ambrosia en van het bladhaantje berekend (afbeelding 4).
afbeelding 4$$, 'inline'),
  ('50314d82-e65d-4e98-b706-5f256296fe12', '9c6eb2dd-806d-4cf0-acc6-707cffe374f7', $$twee uitspraken over de tolerantiecurven$$,
   $$biologie-vwo-2024-ii-bestrijding-van-ambrosia-context13.png$$,
   $$Over de tolerantiecurven worden de volgende uitspraken gedaan:
1 De tolerantie van ambrosia voor de minimumtemperatuur in de koudste maand is groter dan die van O. communa.
2 De maximum-tolerantiewaarden voor de jaarlijkse hoeveelheid neerslag van ambrosia en van O. communa zijn gelijk.$$, 'inline'),
  ('71b26c9e-1d2b-44aa-8aa6-e9e608b10e5d', '9c6eb2dd-806d-4cf0-acc6-707cffe374f7', $$mogelijk ontbrekende biotische factoren in het model$$,
   $$biologie-vwo-2024-ii-bestrijding-van-ambrosia-context14.png$$,
   $$In het model zijn mogelijk belangrijke biotische factoren niet verwerkt.$$, 'inline'),
  ('92541088-3af7-4c10-b818-8e75d4c19a19', '8424b9e2-fa2e-44cb-affa-0bab00f902f0', $$vorming van chylomicronen door darmepitheelcellen; proces P en onderdelen Q, R, S (afbeelding 1)$$,
   $$biologie-vwo-2024-ii-gentherapie-nagemaakt-context1.png$$,
   $$De gentherapie Glybera was effectief bij mensen met lipoproteïnelipase- deficiëntie, een zeldzame stofwisselingsziekte waarbij de stofwisseling van vetten is verstoord. Maar vanwege de hoge kosten is Glybera van de markt gehaald. Een groep onafhankelijke biologen maakt nu een alternatief voor deze gentherapie.
Het vervoer van vetten in de bloedbaan vindt onder andere plaats door chylomicronen. Chylomicronen zijn lipoproteïnen die worden gemaakt door de darmepitheelcellen. Voor de productie van chylomicronen worden de verteringsproducten van vetten gebruikt. In afbeelding 1 is de vorming van chylomicronen door een darmepitheelcel weergegeven. Daarin zijn proces P en de onderdelen Q, R en S aangegeven.
afbeelding 1$$, 'inline'),
  ('9f88a6f5-a32f-4893-83ee-316e667b3fcd', '8424b9e2-fa2e-44cb-affa-0bab00f902f0', $$voor proces P zijn stoffen nodig uit een bepaald orgaan$$,
   $$biologie-vwo-2024-ii-gentherapie-nagemaakt-context2.png$$,
   $$Voor proces P zijn stoffen nodig die worden geproduceerd door een bepaald orgaan.$$, 'inline'),
  ('d38204da-dcf3-4f1f-bd96-75a1e9d7385b', '8424b9e2-fa2e-44cb-affa-0bab00f902f0', $$een deel van de verteringsproducten wordt onbewerkt afgevoerd, een deel verwerkt tot chylomicronen$$,
   $$biologie-vwo-2024-ii-gentherapie-nagemaakt-context3.png$$,
   $$Darmepitheelcellen nemen de producten van de vetvertering op. In afbeelding 1 is te zien dat een deel van deze producten onbewerkt wordt afgevoerd en dat een ander deel wordt bewerkt tot chylomicronen.$$, 'inline'),
  ('338c671c-379b-4372-9068-df964ff2ba2f', '8424b9e2-fa2e-44cb-affa-0bab00f902f0', $$afbraak van chylomicronen door LPL in de haarvaten (afbeelding 2)$$,
   $$biologie-vwo-2024-ii-gentherapie-nagemaakt-context4.png$$,
   $$In de haarvaten van actieve weefsels worden de vetten in de chylomicronen afgebroken door het enzym lipoproteïnelipase (LPL). LPL wordt gemaakt door cellen van verschillende weefsels (zoals vetweefsel en spierweefsel), waarna het wordt afgegeven in de bloedbaan. Daar hecht LPL zich aan het celmembraan van de endotheelcellen. Het enzym breekt vanuit die positie de triglyceriden in de chylomicronen af, waarna de producten (monoglyceriden en vetzuren) door het weefsel kunnen worden opgenomen (afbeelding 2).
afbeelding 2$$, 'inline'),
  ('1b5784f9-07ea-4da5-800c-eff9e98cbfde', '8424b9e2-fa2e-44cb-affa-0bab00f902f0', $$ander gebruik van vetzuren; drie uitspraken over acetyl-CoA, eiwitsynthese en membranen$$,
   $$biologie-vwo-2024-ii-gentherapie-nagemaakt-context5.png$$,
   $$De vetzuren en monoglyceriden die na LPL-activiteit opgenomen kunnen worden, kunnen onder andere gebruikt worden voor de synthese van triglyceriden (vet). De vetzuren kunnen ook op een andere manier gebruikt worden. Hierover worden de volgende uitspraken gedaan: Vetzuren kunnen worden gebruikt voor …
1 de vorming van acetyl-CoA in de mitochondria.
2 de synthese van eiwitten aan de ribosomen.
3 de opbouw van membranen voor organellen.$$, 'inline'),
  ('d3d177e8-d02b-4e5d-8e09-2b0bfcbdce5d', '8424b9e2-fa2e-44cb-affa-0bab00f902f0', $$LPL-deficiëntie geeft een hoog triglyceridegehalte, zichtbaar na centrifugeren (afbeelding 3)$$,
   $$biologie-vwo-2024-ii-gentherapie-nagemaakt-context6.png$$,
   $$Bij mensen met LPL-deficiëntie veroorzaakt een normaal dieet een veel te hoog triglyceridegehalte in het bloed. Een hoog triglyceridegehalte van het bloed is zichtbaar na centrifugeren. De fractie waarin de chylomicronen zich bevinden, is dan anders van kleur dan normaal. In afbeelding 3 is een buisje normaal bloed voor en na centrifugeren weergegeven. De fracties na centrifugeren zijn aangegeven met P en Q.
afbeelding 3
voor na$$, 'inline'),
  ('311e942a-06f3-47d1-987a-b1281542d376', '8424b9e2-fa2e-44cb-affa-0bab00f902f0', $$bloed bevat plasma, rode bloedcellen en witte bloedcellen$$,
   $$biologie-vwo-2024-ii-gentherapie-nagemaakt-context7.png$$,
   $$Bloed bevat onder andere plasma, rode bloedcellen en witte bloedcellen.$$, 'inline'),
  ('9020759b-67b3-4933-92c7-e0b1046a1489', '8424b9e2-fa2e-44cb-affa-0bab00f902f0', $$invuloefening over alvleesklierstoffen bij chronische alvleesklierontsteking$$,
   $$biologie-vwo-2024-ii-gentherapie-nagemaakt-context8.png$$,
   $$Een ander symptoom van LPL-deficiëntie is chronische alvleesklier- ontsteking. De alvleesklier produceert dan minder ...(1)... waardoor de ontlasting dun en vettig is. Ook produceert de alvleesklier dan minder ...(2)... waardoor de glucoseconcentratie van het bloed vaak te hoog is. Bij 1 en 2 moeten de namen van twee stoffen worden ingevuld.$$, 'inline'),
  ('34538019-0ee0-42ee-ac01-d4f75c46d204', '8424b9e2-fa2e-44cb-affa-0bab00f902f0', $$Glybera brengt via een virale vector een functioneel LPL-gen in spiercellen$$,
   $$biologie-vwo-2024-ii-gentherapie-nagemaakt-context9.png$$,
   $$Bij de behandeling met Glybera wordt een functioneel LPL-gen ingebracht. Hierbij is een virus de vector. Dit virus maakt niet ziek en vermenigvuldigt zich niet, maar brengt enkel het functionele LPL-gen in de kern van spiercellen. Daar blijft het gen los in de kern aanwezig. Na injecties met Glybera op zo’n zestig verschillende plaatsen in de beenspieren kan LPL-deficiëntie worden genezen.$$, 'inline'),
  ('96d541b9-f76f-441e-a206-f798c45213ee', '8424b9e2-fa2e-44cb-affa-0bab00f902f0', $$B- en T-celactiviteit wordt geremd tijdens en na de Glybera-behandeling$$,
   $$biologie-vwo-2024-ii-gentherapie-nagemaakt-context10.png$$,
   $$Bij een Glybera-behandeling krijgt de patiënt medicijnen die de activiteit van B- en T-cellen remmen tijdens en vlak na de behandeling.$$, 'inline'),
  ('dc2b976d-67d2-42fc-8189-d28034bd24f3', '8424b9e2-fa2e-44cb-affa-0bab00f902f0', $$ontwikkeling van Slybera: plasmide, E. coli en splitsing tot minicircle (afbeelding 4)$$,
   $$biologie-vwo-2024-ii-gentherapie-nagemaakt-context11.png$$,
   $$De onafhankelijke biologen beweren dat ze op basis van de literatuur over Glybera een alternatief voor de therapie hebben gemaakt: Slybera. Ze plaatsten het LPL-gen in een plasmide en brachten die in bij E. coli. Vervolgens lieten de biologen de E. coli zich vermeerderen. Daarna werden de plasmiden uit de bacteriën gehaald en werd een bepaalde stof toegevoegd om de plasmide in twee delen te splitsen (afbeelding 4). Daarmee werden de overbodige delen uit de plasmide verwijderd en bleef een zo klein mogelijk relevant deel over: de minicircle. Na zuivering konden de minicircles worden geoogst en ingebracht in cellen. De minicircles werden niet in het DNA opgenomen. De biologen hebben aangetoond dat cellen van een zoogdier waarin de minicircles zijn ingebracht, het transgen tot expressie brengen.
afbeelding 4$$, 'inline'),
  ('4e7edbf4-931f-4238-97ae-be20b574a1aa', '8424b9e2-fa2e-44cb-affa-0bab00f902f0', $$vier onderdelen van de plasmide met transgen$$,
   $$biologie-vwo-2024-ii-gentherapie-nagemaakt-context12.png$$,
   $$De plasmide met transgen bevat onder andere de volgende delen:
1 het LPL-gen
2 een gen voor antibioticum-resistentie
3 een promotor voor het LPL-gen
4 de bindingsplaats voor prokaryoot DNA-polymerase$$, 'inline'),
  ('50b1bc2a-6f9c-492a-bee2-ff56f42dc975', '8424b9e2-fa2e-44cb-affa-0bab00f902f0', $$vervolgstappen voor kwaliteit en veiligheid van Slybera, waaronder dierproeven$$,
   $$biologie-vwo-2024-ii-gentherapie-nagemaakt-context13.png$$,
   $$De biologen zijn van plan om Slybera uiteindelijk te verstrekken aan patiënten met LPL-deficiëntie, maar dan moeten de kwaliteit en veiligheid gegarandeerd zijn. Ze zoeken daarom de hulp van andere onderzoekers voor de volgende stappen die moeten worden gedaan, zoals het uitvoeren van dierproeven.$$, 'inline'),
  ('b4bb4ea7-2196-4e52-a19d-f956606c9467', '8424b9e2-fa2e-44cb-affa-0bab00f902f0', $$experimentopzet met 40 LPL-deficiënte muizen$$,
   $$biologie-vwo-2024-ii-gentherapie-nagemaakt-context14.png$$,
   $$Onderzoekers ontwerpen een experiment om de effectiviteit van Slybera op muizen te testen. Ze gebruiken 40 LPL-deficiënte muizen.$$, 'inline'),
  ('e4b9169f-a068-4a08-9679-db914c878dde', '8424b9e2-fa2e-44cb-affa-0bab00f902f0', $$LPL-deficiëntie erft recessief over met allelfrequentie 0,001$$,
   $$biologie-vwo-2024-ii-gentherapie-nagemaakt-context15.png$$,
   $$LPL-deficiëntie erft recessief over. De frequentie van het allel dat verantwoordelijk is voor het ontstaan van LPL-deficiëntie is 0,001.$$, 'inline'),
  ('d13dc47b-3f99-4177-9669-7c61a0572d42', '923dc80d-d992-4f28-a04f-1ae07e0dc3f4', $$inleiding: slaap herstelt DNA-schade in neuronen van gewervelden$$,
   $$biologie-vwo-2024-ii-slaap-herstelt-dna-context1.png$$,
   $$Alle organismen met een zenuwstelsel blijken slaap nodig te hebben. Israëlische wetenschappers toonden aan dat slaap een belangrijke rol speelt bij het herstel van DNA-schade in neuronen.$$, 'inline'),
  ('8dedb2b8-f36a-4d50-9596-1598f4922b20', '923dc80d-d992-4f28-a04f-1ae07e0dc3f4', $$melatonine als slaap-waakhormoon, geproduceerd door de epifyse onder invloed van licht$$,
   $$biologie-vwo-2024-ii-slaap-herstelt-dna-context2.png$$,
   $$Bij gewervelden wordt het slaap-waakritme geregeld door het peptide- hormoon melatonine. Melatonine wordt geproduceerd door de epifyse, een klier in de hersenen. De aanmaak doorloopt een 24 uurs-ritme én wordt beïnvloed door de hoeveelheid licht die door bepaalde receptoren in het netvlies wordt opgevangen. Om in te kunnen slapen moet de melatonineconcentratie boven een bepaalde drempelwaarde komen.$$, 'inline'),
  ('699610cc-3bbd-4cc4-b060-bccc60694ccd', '923dc80d-d992-4f28-a04f-1ae07e0dc3f4', $$melatoninereceptoren op doelwitcellen; drie uitspraken over het werkingsmechanisme$$,
   $$biologie-vwo-2024-ii-slaap-herstelt-dna-context3.png$$,
   $$Op de celmembranen van veel verschillende celtypen zijn melatonine- receptoren te vinden. Zo ook op cellen van het centraal zenuwstelsel. Melatonine heeft verschillende effecten op cellen; het kan bijvoorbeeld de genexpressie beïnvloeden. Drie uitspraken over de doelwitcellen met melatoninereceptoren zijn:
1 Melatonine bereikt de celkern via diffusie.
2 Het effect van melatonine verloopt via second messengers.
3 Melatonine is een transcriptiefactor.$$, 'inline'),
  ('fe159c33-a16c-44f3-9413-e3468089d4d0', '923dc80d-d992-4f28-a04f-1ae07e0dc3f4', $$neuronen zijn overdag actief en lopen dan vooral DNA-schade op$$,
   $$biologie-vwo-2024-ii-slaap-herstelt-dna-context4.png$$,
   $$Doordat neuronen voornamelijk overdag actief zijn, lopen ze voornamelijk overdag DNA-schade op.$$, 'inline'),
  ('fc90f256-c193-4b7a-ac1e-5406d4c25079', '923dc80d-d992-4f28-a04f-1ae07e0dc3f4', $$DNA-schade door zuurstofradicalen die ontstaan bij zuurstofgebruikende processen$$,
   $$biologie-vwo-2024-ii-slaap-herstelt-dna-context5.png$$,
   $$DNA-schade wordt veelal veroorzaakt door zuurstofradicalen. Deze stoffen ontstaan bij processen waarbij zuurstof wordt gebruikt.$$, 'inline'),
  ('00155485-e71c-4288-a7f0-9166b6e422e2', '923dc80d-d992-4f28-a04f-1ae07e0dc3f4', $$DNA-schade ontstaat als gevolg van ATP-productie$$,
   $$biologie-vwo-2024-ii-slaap-herstelt-dna-context6.png$$,
   $$De DNA-schade ontstaat als gevolg van de productie van ATP.$$, 'inline'),
  ('843beeff-16c7-4afa-be8f-6bab64b36b7d', '923dc80d-d992-4f28-a04f-1ae07e0dc3f4', $$dubbelstrengsbreuk (dsb) en reparatie via inserties of deleties$$,
   $$biologie-vwo-2024-ii-slaap-herstelt-dna-context7.png$$,
   $$Een voorbeeld van DNA-schade is een dubbelstrengsbreuk (dsb). Bij een dsb zijn beide strengen van een DNA-molecuul gebroken. Bij de reparatie van dsb’s kunnen soms inserties of deleties optreden.$$, 'inline'),
  ('97d54142-471d-41dc-8100-a3de4285e6be', '923dc80d-d992-4f28-a04f-1ae07e0dc3f4', $$twee uitspraken over het effect van inserties en deleties$$,
   $$biologie-vwo-2024-ii-slaap-herstelt-dna-context8.png$$,
   $$Over inserties en deleties worden de volgende uitspraken gedaan:
1 Een insertie kan leiden tot een leesraamverschuiving.
2 Een deletie kan leiden tot de synthese van een langer eiwit.$$, 'inline'),
  ('d43b9154-66fa-4e87-a6ce-ff95fee07d31', '923dc80d-d992-4f28-a04f-1ae07e0dc3f4', $$onderzoeksopzet met zebravis-larven: GFP op telomeren maakt chromosoomdynamiek zichtbaar (afbeelding 1, afbeelding 2)$$,
   $$biologie-vwo-2024-ii-slaap-herstelt-dna-context9.png$$,
   $$De Israëlische wetenschappers onderzochten of slaap nodig is om dsb’s in neuronen te herstellen. Zij voerden dit onderzoek uit met larven van zebravisjes (afbeelding 1). Zebravisjes zijn vissen die overdag actief zijn. De larven zijn doorzichtig, waardoor het centraal zenuwstelsel goed zichtbaar is. De onderzoekers modificeerden de zebravisjes zodat ze in hun neuronen een groen-fluorescerend eiwit aanmaken dat bindt aan de chromosoomuiteinden (telomeren). Op deze manier maakten ze de beweeglijkheid van chromosomen (chromosoomdynamiek) zichtbaar in het zenuwstelsel van levende zebravis-larven (afbeelding 2). De onderzoekers gebruikten de chromosoomdynamiek als maat voor DNA-herstel. De chromosoomdynamiek wordt onder andere beïnvloed door de mate van spiralisatie van de chromatinedraad en door reparatieprocessen. De chromosoomdynamiek wordt uitgedrukt in de hoeveelheid ruimte waarbinnen de uiteinden van chromosomen bewegen. De lichte plaatsen op de foto in afbeelding 2 geven cellen aan met veel chromosoomdynamiek.
afbeelding 1 afbeelding 2$$, 'inline'),
  ('4fec959e-d00d-4927-b56c-8a2cc2cc13b4', '923dc80d-d992-4f28-a04f-1ae07e0dc3f4', $$grote chromosoomdynamiek tijdens slaap; stimuleren van neuronen vermindert dit$$,
   $$biologie-vwo-2024-ii-slaap-herstelt-dna-context10.png$$,
   $$Vooral tijdens de slaap van de zebravis-larven namen de onderzoekers grote chromosoomdynamiek waar in neuronen. Als ze – tijdens de slaap – de activiteit van neuronen stimuleerden, nam de chromosoomdynamiek af.$$, 'inline'),
  ('6aedbb64-d7e5-4a05-994a-8740ec8dfd2d', '923dc80d-d992-4f28-a04f-1ae07e0dc3f4', $$chromosoomdynamiek als maat voor DNA-herstel, bevestigd via meting van γH2AX$$,
   $$biologie-vwo-2024-ii-slaap-herstelt-dna-context11.png$$,
   $$De onderzoekers konden vaststellen dat chromosoomdynamiek inderdaad een goede maat is voor DNA-herstel, door in de neuronen van de zebravis-larven ook de stof γH2AX te meten. Bij het optreden van een dsb wordt γH2AX gevormd uit het histon-eiwit H2AX. Op plaatsen waar veel γH2AX aanwezig is dus zeer waarschijnlijk een dsb aanwezig.$$, 'inline'),
  ('8cdeca6d-c222-4346-8f20-28f915ebb90a', '923dc80d-d992-4f28-a04f-1ae07e0dc3f4', $$omzetting van H2AX in γH2AX vermindert de spiralisatie van de chromatinedraad$$,
   $$biologie-vwo-2024-ii-slaap-herstelt-dna-context12.png$$,
   $$De omzetting van H2AX in γH2AX maakt de reparatie van een dsb mogelijk doordat het de spiralisatie van de chromatinedraad vermindert.$$, 'inline'),
  ('54dfe9d7-f663-47c2-a28f-e126a430a041', '923dc80d-d992-4f28-a04f-1ae07e0dc3f4', $$gemeten hoeveelheid γH2AX en chromosoomdynamiek gedurende 25 uur (afbeelding 3)$$,
   $$biologie-vwo-2024-ii-slaap-herstelt-dna-context13.png$$,
   $$Afbeelding 3 toont de gemeten hoeveelheid γH2AX en de chromosoom- dynamiek in neuronen van zebravis-larven gedurende 25 uur.
afbeelding 3$$, 'inline'),
  ('680853a2-448f-47b8-a2ee-a4b08f311c0b', '923dc80d-d992-4f28-a04f-1ae07e0dc3f4', $$de legenda van afbeelding 3 toont niet welke lijn bij welke as hoort$$,
   $$biologie-vwo-2024-ii-slaap-herstelt-dna-context14.png$$,
   $$In de legenda is niet weergegeven welke lijn bij welke as hoort.$$, 'inline'),
  ('480ed919-eace-4f78-bf5a-71879cad2e13', '923dc80d-d992-4f28-a04f-1ae07e0dc3f4', $$experiment met melatonine-toediening: slaapduur en chromosoomdynamiek (afbeelding 4, afbeelding 5)$$,
   $$biologie-vwo-2024-ii-slaap-herstelt-dna-context15.png$$,
   $$Om te bepalen hoe slaap en chromosoomdynamiek samenhangen, deden de onderzoekers een experiment waarbij een groep zebravis-larven overdag melatonine in een oplosmiddel toegediend kreeg. Een andere groep zebravis-larven kreeg alleen het oplosmiddel toegediend (controle). Afbeelding 4 toont de slaapduur vlak voor en na toediening. Afbeelding 5 toont de chromosoomdynamiek drie uur na toediening.
afbeelding 4 afbeelding 5$$, 'inline'),
  ('4643e494-6b0f-485e-8089-0f5127605c98', 'd5e1ec76-408c-47d0-9e66-8998ae88cee7', $$inleiding: onderzoek naar het effect van sigarettenpeuken op Engels raaigras en witte klaver$$,
   $$biologie-vwo-2024-ii-schadelijke-peuken-context1.png$$,
   $$Onderzoek heeft aangetoond dat weggegooide sigarettenpeuken verstoringen in ecosystemen kunnen veroorzaken. Ecologen van de University of Cambridge onderzochten de invloed van sigarettenpeuken op de twee plantensoorten die veel in grasvelden van parken te vinden zijn: Engels raaigras en witte klaver.$$, 'inline'),
  ('fa71487a-8ef2-4b16-aa5a-a46edb2e444a', 'd5e1ec76-408c-47d0-9e66-8998ae88cee7', $$drie typen sigarettenfilters; kiemingssucces op de verschillende bodems (afbeelding 1)$$,
   $$biologie-vwo-2024-ii-schadelijke-peuken-context2.png$$,
   $$In het onderzoek werden drie typen sigarettenfilters gebruikt: filters van ongerookte sigaretten (schone filters), filters van gerookte sigaretten (filters zonder tabak) en filters van gerookte sigaretten waaraan nog een beetje tabak achter was gebleven (filters met tabak). Afbeelding 1 toont het percentage zaden dat is gekiemd (het kiemingssucces) van Engels raaigras en witte klaver, gezaaid op bodems met de drie typen filters en op controle-bodems.
afbeelding 1$$, 'inline'),
  ('a0862786-61ad-40e9-9da2-7437a2fab0c4', 'd5e1ec76-408c-47d0-9e66-8998ae88cee7', $$definitie van het relatieve kiemingssucces, met voorbeeld voor Engels raaigras$$,
   $$biologie-vwo-2024-ii-schadelijke-peuken-context3.png$$,
   $$Het relatieve kiemingssucces is de mate waarin de kieming van de behandeling verschilt van de controle. In het geval van Engels raaigras is dit in aanwezigheid van filters met tabak 83%.$$, 'inline'),
  ('af985e40-f90b-4f2b-8fa9-92e37ef1befd', 'd5e1ec76-408c-47d0-9e66-8998ae88cee7', $$metingen na 21 dagen: stengellengte, wortelgewicht en chlorofylgehalte (tabel)$$,
   $$biologie-vwo-2024-ii-schadelijke-peuken-context4.png$$,
   $$Eenentwintig dagen nadat de planten gekiemd waren, werden verschillende metingen gedaan aan de planten. De tabel toont de resultaten van planten die gegroeid waren op bodems met filters met tabak ten opzichte van planten die gegroeid waren op de controlebodems.
Engels raaigras witte klaver lengte stengels –13% –28% drooggewicht wortels geen significant verschil –57% gehalte chlorofyl a geen significant verschil +10% gehalte chlorofyl b –18% geen significant verschil$$, 'inline'),
  ('ac6ac3a4-ea60-4ec9-8282-c007b6834c27', 'd5e1ec76-408c-47d0-9e66-8998ae88cee7', $$het grootste effect van de sigarettenpeuken is het lagere wortelgewicht bij witte klaver$$,
   $$biologie-vwo-2024-ii-schadelijke-peuken-context5.png$$,
   $$Het grootste effect is het lagere wortelgewicht in witte klaver.$$, 'inline'),
  ('d6b06a24-01c5-4e05-a621-e96e7d34e889', 'd5e1ec76-408c-47d0-9e66-8998ae88cee7', $$de afname van het chlorofyl b-gehalte bij Engels raaigras beïnvloedt de fotosynthese$$,
   $$biologie-vwo-2024-ii-schadelijke-peuken-context6.png$$,
   $$De afname van het gehalte chlorofyl b bij Engels raaigras heeft invloed op de fotosynthese.$$, 'inline'),
  ('311a7652-f919-40bb-9f19-f4dfe3874b23', 'd5e1ec76-408c-47d0-9e66-8998ae88cee7', $$witte klaver als vlinderbloemige met stikstoffixerende knolletjesbacteriën$$,
   $$biologie-vwo-2024-ii-schadelijke-peuken-context7.png$$,
   $$In het onderzoek werden Engels raaigras en witte klaver gekweekt op bodems waarin de omstandigheden voor plantengroei optimaal zijn. Witte klaver behoort tot de vlinderbloemigen, die een symbiose kunnen aangaan met knolletjes-bacteriën. In de natuurlijke situatie beïnvloedt de symbiose het succes van witte klaver.$$, 'inline'),
  ('c1a404ff-f0e8-4df1-8c21-6c7d8932b10e', 'd5e1ec76-408c-47d0-9e66-8998ae88cee7', $$sigarettenpeuken verminderen de stengelgroei van witte klaver, wat de bacteriën benadeelt$$,
   $$biologie-vwo-2024-ii-schadelijke-peuken-context8.png$$,
   $$De vervuiling met sigarettenpeuken is ook nadelig voor de knolletjesbacteriën, doordat stengelgroei van de witte klaver afneemt.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('39967b4e-7c3f-4ca4-8882-74517f5676d3', '0f05899c-9d3e-434e-9a44-cdb360720482', 1,
   '[{"domain": "Populatie- en ecosysteemniveau", "subdomain": "Soortvorming"}]'::jsonb,
   '["soortdefinitie", "biologisch soortbegrip", "voortplantingsisolatie", "taxonomie"]'::jsonb,
   $$Beargumenteren van een soortnaam op basis van het biologische soortbegrip.$$,
   $$biologie-vwo-2024-ii-de-herintroductie-van-het-przewalskipaard-vraag1.png$$, $$1p 1 Noteer welke naam je dan kiest, en geef een biologisch argument dat jouw keuze ondersteunt.$$, array['5fc3e17d-1474-48bd-97e5-1ecd7014766f', 'a7394afb-59a4-4f48-8a6a-a693f208d49e']::uuid[]),
  ('74abb9b5-cfab-4509-9cfa-25ad513f4b11', '0f05899c-9d3e-434e-9a44-cdb360720482', 2,
   '[{"domain": "Populatie- en ecosysteemniveau", "subdomain": "Soortvorming"}]'::jsonb,
   '["cladogram", "verwantschap", "evolutionaire boom", "fylogenie"]'::jsonb,
   $$Beoordelen of uitspraken over verwantschap worden ondersteund door een cladogram.$$,
   $$biologie-vwo-2024-ii-de-herintroductie-van-het-przewalskipaard-vraag2.png$$, $$2p 2 Schrijf de nummers 1, 2 en 3 onder elkaar en noteer erachter of de betreffende uitspraak wel of niet door het cladogram wordt ondersteund.$$, array['7591d4b0-4898-4794-b48e-995f3c06642c', '6c397c7f-4254-4713-8dc7-a5466d9a61d8']::uuid[]),
  ('c10573f6-0bb6-4dd2-90e6-707d135d241b', '0f05899c-9d3e-434e-9a44-cdb360720482', 3,
   '[{"domain": "Populatie- en ecosysteemniveau", "subdomain": "Soortvorming"}]'::jsonb,
   '["flessenhalseffect", "genenpool", "populatieomvang", "genetische drift"]'::jsonb,
   $$Benoemen van het flessenhalseffect als gevolg van een sterke afname van de populatiegrootte.$$,
   $$biologie-vwo-2024-ii-de-herintroductie-van-het-przewalskipaard-vraag3.png$$, $$1p 3 Wat is de naam voor de afname van de genenpool als gevolg van een enorme afname van de populatiegrootte?
A gene flow
B het flessenhalseffect (bottleneckeffect)
